create or replace function private.fin_goal_entry(p_user uuid, p_op text, p_id uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.savings_goal_entries%rowtype;
  v_goal public.savings_goals%rowtype;
  v_saved bigint;
begin
  if p_op = 'delete' then
    select * into v_row from public.savings_goal_entries where id = p_id and user_id = p_user for update;
    if not found then
      return private.result('applied', jsonb_build_object('note', 'already_deleted'));
    end if;
    -- Removing a contribution must not leave the goal with a negative saved amount.
    if v_row.kind = 'contribution' then
      perform 1 from public.savings_goals where id = v_row.goal_id for update;
      select coalesce(sum(case when kind = 'contribution' then amount_minor else -amount_minor end), 0)
        into v_saved from public.savings_goal_entries where goal_id = v_row.goal_id;
      if v_saved - v_row.amount_minor < 0 then
        raise exception 'Remove the later withdrawals first: this would make the saved amount negative.'
          using errcode = 'P0001';
      end if;
    end if;
    delete from public.savings_goal_entries where id = p_id;
    return private.result('applied');
  end if;

  if exists (select 1 from public.savings_goal_entries where id = p_id) then
    raise exception 'Not found' using errcode = '42501';
  end if;
  select * into v_goal from public.savings_goals where id = (p ->> 'goal_id')::uuid and user_id = p_user;
  if not found then
    raise exception 'Goal not found' using errcode = '42501';
  end if;
  if v_goal.status = 'archived' then
    raise exception 'This goal is archived.' using errcode = 'P0001';
  end if;
  insert into public.savings_goal_entries (id, user_id, goal_id, kind, amount_minor, occurred_on, note)
  values (p_id, p_user, v_goal.id, p ->> 'kind', (p ->> 'amount_minor')::bigint,
    (p ->> 'occurred_on')::date, private.jtext(p, 'note'))
  returning * into v_row;
  if v_row.kind = 'contribution' then
    perform private.check_goal_milestones(p_user, v_goal.id);
  end if;
  return private.result('applied', jsonb_build_object('record', to_jsonb(v_row)));
end;
$$;
revoke all on function private.fin_goal_entry(uuid, text, uuid, jsonb) from public;

-- -----------------------------------------------------------------------------
-- The public entry point
-- -----------------------------------------------------------------------------
create or replace function public.apply_finance_mutation(
  p_mutation_id uuid,
  p_entity text,
  p_operation text,
  p_record_id uuid,
  p_payload jsonb,
  p_base_version bigint default null,
  p_device_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_existing jsonb;
  v_result jsonb;
  v_device uuid;
  v_message text;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_mutation_id is null or p_record_id is null then
    raise exception 'Mutation and record ids are required' using errcode = '22023';
  end if;
  if not (
    (p_entity = 'transaction' and p_operation in ('create', 'update', 'delete'))
    or (p_entity in ('financial_account', 'category', 'budget', 'savings_goal') and p_operation in ('create', 'update'))
    or (p_entity = 'savings_goal_entry' and p_operation in ('create', 'delete'))
  ) then
    raise exception 'Unsupported mutation: % %', p_entity, p_operation using errcode = '22023';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' or pg_column_size(p_payload) > 8192 then
    raise exception 'Invalid payload' using errcode = '22023';
  end if;

  -- Serialise concurrent deliveries of the same mutation, then replay if already done.
  perform pg_advisory_xact_lock(hashtextextended(v_user::text || ':' || p_mutation_id::text, 0));
  select r.response into v_existing
  from public.sync_receipts r
  where r.user_id = v_user and r.client_mutation_id = p_mutation_id;
  if found then
    return coalesce(v_existing, private.result('applied')) || jsonb_build_object('replayed', true);
  end if;

  -- Register the device (ignored if the id belongs to someone else).
  if p_device_id is not null then
    insert into public.user_devices (id, user_id) values (p_device_id, v_user)
    on conflict (id) do update set last_seen_at = now(), last_sync_at = now()
      where public.user_devices.user_id = v_user;
    select id into v_device from public.user_devices where id = p_device_id and user_id = v_user;
  end if;

  begin
    v_result := case p_entity
      when 'transaction' then private.fin_transaction(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'financial_account' then private.fin_account(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'category' then private.fin_category(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'budget' then private.fin_budget(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'savings_goal' then private.fin_goal(v_user, p_operation, p_record_id, p_payload, p_base_version)
      when 'savings_goal_entry' then private.fin_goal_entry(v_user, p_operation, p_record_id, p_payload)
    end;
  exception
    when insufficient_privilege then
      -- Never reveal whether a record exists for another user.
      v_result := private.result('rejected', jsonb_build_object('message', 'Not found.'));
    when unique_violation then
      v_result := private.result('rejected', jsonb_build_object('message', 'Something with that name already exists.'));
    when check_violation or not_null_violation or foreign_key_violation then
      v_result := private.result('rejected', jsonb_build_object('message', 'Some of the details are not valid.'));
    when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format
      or datetime_field_overflow or invalid_parameter_value or raise_exception then
      get stacked diagnostics v_message = message_text;
      v_result := private.result('rejected', jsonb_build_object('message', left(v_message, 200)));
  end;

  insert into public.sync_receipts (
    user_id, client_mutation_id, device_id, entity, record_id, operation, result, server_version, response
  ) values (
    v_user, p_mutation_id, v_device, p_entity, p_record_id, p_operation,
    v_result ->> 'status', (v_result ->> 'server_version')::bigint, v_result
  );

  if p_entity = 'transaction' and v_result ->> 'status' <> 'applied' then
    perform private.record_finance_event(v_user, 'sync_failed', 'sync_failed:' || p_mutation_id,
      jsonb_build_object('mutation_id', p_mutation_id, 'record_id', p_record_id,
        'status', v_result ->> 'status', 'reason', v_result ->> 'reason'));
  end if;
  return v_result;
end;
$$;
revoke all on function public.apply_finance_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) from public, anon;
grant execute on function public.apply_finance_mutation(uuid, text, text, uuid, jsonb, bigint, uuid) to authenticated;

-- One "sync completed" fact per offline sync batch (dedupe by batch id).
create or replace function public.record_sync_completed(p_batch_id uuid, p_applied integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_applied is null or p_applied < 1 or p_applied > 1000 then
    raise exception 'Invalid count' using errcode = '22023';
  end if;
  perform private.record_finance_event(v_user, 'sync_completed', 'sync_completed:' || p_batch_id,
    jsonb_build_object('applied', p_applied));
end;
$$;
revoke all on function public.record_sync_completed(uuid, integer) from public, anon;
grant execute on function public.record_sync_completed(uuid, integer) to authenticated;

-- >>> 20261101000300_finance_reads.sql
-- =============================================================================
-- AVEN Stage 2 — Migration 7: Finance read models
--
-- Every view/function here is SECURITY INVOKER: it runs as the signed-in user,
-- so Row Level Security limits results to that user's own rows.
-- Aggregated money is returned as TEXT so large sums stay exact in JavaScript.
-- Transfers are NEVER counted as income or expenses.
-- =============================================================================

-- Balance = opening balance + income − expenses − transfers out + transfers in.
create view public.account_balances
with (security_invoker = true)
as
select
  a.id as account_id,
  a.user_id,
  a.currency_code,
  (a.opening_balance_minor + coalesce(sum(
    case
      when t.kind = 'income' then t.amount_minor
      when t.kind = 'expense' then -t.amount_minor
      when t.kind = 'transfer' and t.account_id = a.id then -t.amount_minor
      when t.kind = 'transfer' and t.transfer_account_id = a.id then t.amount_minor
      else 0
    end), 0))::text as balance_minor,
  count(t.id)::integer as transaction_count,
  max(t.occurred_on) as last_activity_on
from public.financial_accounts a
left join public.transactions t
  on t.user_id = a.user_id and (t.account_id = a.id or t.transfer_account_id = a.id)
group by a.id;

revoke all on public.account_balances from anon, authenticated;
grant select on public.account_balances to authenticated;

create view public.savings_goal_progress
with (security_invoker = true)
as
select
  g.id as goal_id,
  g.user_id,
  coalesce(sum(case when e.kind = 'contribution' then e.amount_minor else -e.amount_minor end), 0)::text as saved_minor,
  count(e.id)::integer as entry_count
from public.savings_goals g
left join public.savings_goal_entries e on e.goal_id = g.id
group by g.id;

revoke all on public.savings_goal_progress from anon, authenticated;
grant select on public.savings_goal_progress to authenticated;

-- Income / expense / net per currency for a date range (inclusive).
create or replace function public.finance_summary(p_from date, p_to date)
returns table (
  currency_code text,
  income_minor text,
  expense_minor text,
  net_minor text,
  transaction_count integer
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    t.currency_code,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)::text,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0)::text,
    (coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)
      - coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0))::text,
    count(*)::integer
  from public.transactions t
  where t.kind in ('income', 'expense') and t.occurred_on between p_from and p_to
  group by t.currency_code
  order by t.currency_code;
$$;

create or replace function public.spending_by_category(p_from date, p_to date)
returns table (
  currency_code text,
  category_id uuid,
  category_name text,
  expense_minor text
)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.currency_code, t.category_id, coalesce(c.name, 'Uncategorised'), sum(t.amount_minor)::text
  from public.transactions t
  left join public.transaction_categories c on c.id = t.category_id
  where t.kind = 'expense' and t.occurred_on between p_from and p_to
  group by t.currency_code, t.category_id, c.name
  order by t.currency_code, sum(t.amount_minor) desc;
$$;

-- Month-by-month income and expenses for the last p_months months ending at p_today's month.
create or replace function public.monthly_cashflow(p_months integer, p_today date)
returns table (
  month date,
  currency_code text,
  income_minor text,
  expense_minor text
)
language sql
stable
security invoker
set search_path = ''
as $$
  with bounds as (
    select date_trunc('month', p_today)::date as last_month,
           (date_trunc('month', p_today) - make_interval(months => greatest(1, least(p_months, 24)) - 1))::date as first_month
  ),
  currencies as (
    select distinct t.currency_code from public.transactions t, bounds b
    where t.kind in ('income', 'expense') and t.occurred_on >= b.first_month
  ),
  months as (
    select generate_series(b.first_month, b.last_month, interval '1 month')::date as month from bounds b
  )
  select m.month, c.currency_code,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'income'), 0)::text,
    coalesce(sum(t.amount_minor) filter (where t.kind = 'expense'), 0)::text
  from months m
  cross join currencies c
  left join public.transactions t
    on t.currency_code = c.currency_code and t.kind in ('income', 'expense')
    and t.occurred_on >= m.month and t.occurred_on < (m.month + interval '1 month')
  group by m.month, c.currency_code
  order by c.currency_code, m.month;
$$;

-- Spending against each budget for one month. Expenses only; matching currency only.
create or replace function public.budget_progress(p_month date, p_include_archived boolean default false)
returns table (
  budget_id uuid,
  name text,
  category_id uuid,
  category_name text,
  currency_code text,
  limit_minor text,
  spent_minor text,
  alert_threshold_pct smallint,
  starts_on date,
  archived boolean,
  version bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select b.id, b.name, b.category_id, c.name, b.currency_code, b.limit_minor::text,
    coalesce((
      select sum(t.amount_minor) from public.transactions t
      where t.user_id = b.user_id and t.kind = 'expense' and t.currency_code = b.currency_code
        and t.occurred_on >= date_trunc('month', p_month)::date
        and t.occurred_on < (date_trunc('month', p_month) + interval '1 month')::date
        and (b.category_id is null or t.category_id = b.category_id)
    ), 0)::text,
    b.alert_threshold_pct, b.starts_on, b.archived_at is not null, b.version
  from public.budgets b
  left join public.transaction_categories c on c.id = b.category_id
  where (p_include_archived or b.archived_at is null)
  order by b.archived_at nulls first, b.name;
$$;

create or replace function public.budget_history(p_budget_id uuid, p_months integer, p_today date)
returns table (month date, spent_minor text, limit_minor text)
language sql
stable
security invoker
set search_path = ''
as $$
  with b as (select * from public.budgets where id = p_budget_id),
  months as (
    select generate_series(
      greatest((select starts_on from b),
        (date_trunc('month', p_today) - make_interval(months => greatest(1, least(p_months, 24)) - 1))::date),
      date_trunc('month', p_today)::date,
      interval '1 month')::date as month
  )
  select m.month,
    coalesce((
      select sum(t.amount_minor) from public.transactions t, b
      where t.kind = 'expense' and t.currency_code = b.currency_code
        and t.occurred_on >= m.month and t.occurred_on < (m.month + interval '1 month')
        and (b.category_id is null or t.category_id = b.category_id)
    ), 0)::text,
    (select limit_minor from b)::text
  from months m
  where exists (select 1 from b)
  order by m.month desc;
$$;

-- Searchable, filterable, sortable transaction list with names and total count.
create or replace function public.list_transactions(
  p_q text default null,
  p_kind text default null,
  p_account_id uuid default null,
  p_category_id uuid default null,
  p_from date default null,
  p_to date default null,
  p_sort text default 'date_desc',
  p_limit integer default 50,
  p_offset integer default 0
)
returns table (
  id uuid,
  kind text,
  account_id uuid,
  account_name text,
  transfer_account_id uuid,
  transfer_account_name text,
  amount_minor bigint,
  currency_code text,
  category_id uuid,
  category_name text,
  description text,
  merchant text,
  notes text,
  occurred_on date,
  version bigint,
  created_at timestamptz,
  updated_at timestamptz,
  total_count bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.id, t.kind, t.account_id, a.name, t.transfer_account_id, ta.name, t.amount_minor, t.currency_code,
    t.category_id, c.name, t.description, t.merchant, t.notes, t.occurred_on, t.version, t.created_at,
    t.updated_at, count(*) over ()
  from public.transactions t
  join public.financial_accounts a on a.id = t.account_id
  left join public.financial_accounts ta on ta.id = t.transfer_account_id
  left join public.transaction_categories c on c.id = t.category_id
  where (p_kind is null or t.kind = p_kind)
    and (p_account_id is null or t.account_id = p_account_id or t.transfer_account_id = p_account_id)
    and (p_category_id is null or t.category_id = p_category_id)
    and (p_from is null or t.occurred_on >= p_from)
    and (p_to is null or t.occurred_on <= p_to)
    and (
      p_q is null or btrim(p_q) = ''
      or position(lower(btrim(p_q)) in lower(
        coalesce(t.description, '') || ' ' || coalesce(t.merchant, '') || ' ' || coalesce(t.notes, '')
        || ' ' || coalesce(c.name, ''))) > 0
    )
  order by
    case when p_sort = 'amount_desc' then t.amount_minor end desc nulls last,
    case when p_sort = 'amount_asc' then t.amount_minor end asc nulls last,
    case when p_sort = 'date_asc' then t.occurred_on end asc nulls last,
    t.occurred_on desc, t.created_at desc
  limit greatest(1, least(p_limit, 200)) offset greatest(0, p_offset);
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.finance_summary(date, date)',
    'public.spending_by_category(date, date)',
    'public.monthly_cashflow(integer, date)',
    'public.budget_progress(date, boolean)',
    'public.budget_history(uuid, integer, date)',
    'public.list_transactions(text, text, uuid, uuid, date, date, text, integer, integer)'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end
$$;

commit;
